{
  "title": "A slower Kyoto",
  "summary": "A gentler day with one temple, one evening stroll, and two unhurried vegan meals.",
  "stops": [
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "Shoes off, phone down, eyes up. A single calm temple beats three rushed ones.",
      "must_do_id": null
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at a gentle vegan table, no one glancing at a watch.",
      "must_do_id": null
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": "m3",
      "note": "The one must-do stays. After dark, lanterns do the work.",
      "must_do_id": "m3"
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner back at the same kind kitchen, because a slow day can end where it began.",
      "must_do_id": null
    }
  ]
}
